mapper.select:
SELECT q.id AS id, q.space_no AS spaceNo, q.query_time AS queryTime, q.query_user_id AS queryUserId, u.nickname AS queryUserName, q.area_id AS areaId, a.name AS areaName, q.space_status AS spaceStatus, q.remark AS remark, q.reserve1 AS reserve1, q.reserve2 AS reserve2, q.creator AS creator, q.updater AS updater, q.create_time AS createTime, q.update_time AS updateTime FROM space_query q LEFT JOIN area_info a ON q.area_id = a.id AND a.deleted = 0 LEFT JOIN user_info u ON q.query_user_id = u.id AND u.deleted = 0 WHERE q.deleted = 0
AND q.space_no LIKE CONCAT('%', #{reqVO.spaceNo}, '%')
AND q.query_time BETWEEN FROM_UNIXTIME(#{reqVO.queryTimeNew[0]}) AND FROM_UNIXTIME(#{reqVO.queryTimeNew[1]})
AND q.query_user_id = #{reqVO.queryUserId}
AND q.area_id = #{reqVO.areaId}
AND q.space_status = #{reqVO.spaceStatus}
AND q.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY q.id DESC

SELECT q.space_no AS spaceNo, a.lon AS lon, a.lat AS lat, q.space_status AS spaceStatus FROM space_query q LEFT JOIN area_info a ON q.area_id = a.id AND a.deleted = 0 WHERE q.deleted = 0
AND q.area_id = #{reqVO.areaId}
GROUP BY q.id, q.space_no, a.lon, a.lat, q.space_status
